package com.bankscanner;

import lombok.Data;

/**
 * Immutable snapshot of a single bank stack used for display and sorting.
 */
@Data
public class BankItem
{
	private final int id;
	private final String name;
	private final int quantity;
	private final int gePrice;      // unit GE price
	private final int haPrice;      // unit high alch price
	private final long totalValue;  // quantity * gePrice
	private final boolean members;
	private final boolean tradeable;
	private final boolean placeholder;

	public BankItem(int id, String name, int quantity, int gePrice, int haPrice,
		boolean members, boolean tradeable, boolean placeholder)
	{
		this.id = id;
		this.name = name;
		this.quantity = quantity;
		this.gePrice = gePrice;
		this.haPrice = haPrice;
		this.totalValue = (long) quantity * gePrice;
		this.members = members;
		this.tradeable = tradeable;
		this.placeholder = placeholder;
	}
}

package com.bankscanner;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("bankscannerplugin")
public interface BankScannerConfig extends Config
{
	@ConfigSection(
		name = "Display",
		description = "How items are shown in the panel",
		position = 0
	)
	String displaySection = "displaySection";

	@ConfigItem(
		keyName = "showGePrice",
		name = "Show GE price",
		description = "Display Grand Exchange unit price for each item",
		section = displaySection,
		position = 0
	)
	default boolean showGePrice()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTotalValue",
		name = "Show total value",
		description = "Display quantity × GE price for each stack",
		section = displaySection,
		position = 1
	)
	default boolean showTotalValue()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showHaPrice",
		name = "Show High Alch",
		description = "Display high alchemy value for each item",
		section = displaySection,
		position = 2
	)
	default boolean showHaPrice()
	{
		return false;
	}

	@ConfigItem(
		keyName = "hidePlaceholders",
		name = "Hide placeholders",
		description = "Do not list bank placeholders (empty slots with placeholder icons)",
		section = displaySection,
		position = 3
	)
	default boolean hidePlaceholders()
	{
		return true;
	}

	@ConfigItem(
		keyName = "autoOpenPanel",
		name = "Open panel on bank open",
		description = "Automatically expand the Bank Scanner side panel when the bank is opened",
		section = displaySection,
		position = 4
	)
	default boolean autoOpenPanel()
	{
		return false;
	}
}

package com.bankscanner;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JScrollPane;
import javax.swing.JSeparator;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.LinkBrowser;
import net.runelite.client.util.QuantityFormatter;

public class BankScannerPanel extends PluginPanel
{
	private static final String WIKI_BASE = "https://oldschool.runescape.wiki/w/";
	private static final int ICON_SIZE = 32;

	private final BankScannerConfig config;
	private final ItemManager itemManager;
	private Runnable onRescan;

	private final JTextField searchField = new JTextField();
	private final JTextField minQtyField = new JTextField("0");
	private final JTextField minPriceField = new JTextField("0");
	private final JComboBox<SortMode> sortCombo = new JComboBox<>(SortMode.values());
	private final JButton sortOrderBtn = new JButton("Ascending");
	private boolean sortAscending = true;
	private final JCheckBox membersOnlyCheck = new JCheckBox("Members only", false);
	private final JCheckBox tradeableOnlyCheck = new JCheckBox("Tradeable only", false);
	private final JCheckBox showHaCheck = new JCheckBox("Show High Alch", false);
	private final JCheckBox onlyUntradeableCheck = new JCheckBox("Only untradeable", false);
	private final JLabel statusLabel = new JLabel("Open your bank to scan items.");
	private final JLabel totalLabel = new JLabel("");
	private final JPanel itemListPanel = new JPanel();

	private List<BankItem> allItems = new ArrayList<>();

	public BankScannerPanel(BankScannerConfig config, ItemManager itemManager)
	{
		super(false);
		this.config = config;
		this.itemManager = itemManager;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		// ===== Settings / filters header =====
		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(new EmptyBorder(8, 8, 8, 8));

		JLabel title = new JLabel("Bank Scanner");
		title.setForeground(Color.WHITE);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.add(title);
		header.add(Box.createVerticalStrut(6));

		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		statusLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.add(statusLabel);

		totalLabel.setForeground(ColorScheme.BRAND_ORANGE);
		totalLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.add(totalLabel);

		header.add(Box.createVerticalStrut(8));

		// Search
		JLabel searchLabel = new JLabel("Search name:");
		searchLabel.setForeground(Color.LIGHT_GRAY);
		searchLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.add(searchLabel);
		searchField.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		searchField.setAlignmentX(Component.LEFT_ALIGNMENT);
		searchField.getDocument().addDocumentListener(simpleListener(this::refreshList));
		header.add(searchField);
		header.add(Box.createVerticalStrut(4));

		// Filters row
		JPanel filterRow = new JPanel(new GridLayout(2, 2, 4, 4));
		filterRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		filterRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		filterRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 60));

		JLabel minQtyLbl = new JLabel("Min qty:");
		minQtyLbl.setForeground(Color.LIGHT_GRAY);
		filterRow.add(minQtyLbl);
		minQtyField.getDocument().addDocumentListener(simpleListener(this::refreshList));
		filterRow.add(minQtyField);

		JLabel minPriceLbl = new JLabel("Min GE price:");
		minPriceLbl.setForeground(Color.LIGHT_GRAY);
		filterRow.add(minPriceLbl);
		minPriceField.getDocument().addDocumentListener(simpleListener(this::refreshList));
		filterRow.add(minPriceField);

		header.add(filterRow);
		header.add(Box.createVerticalStrut(4));

		// Sort dropdown
		sortCombo.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		sortCombo.setAlignmentX(Component.LEFT_ALIGNMENT);
		sortCombo.addActionListener(e -> refreshList());
		header.add(sortCombo);
		header.add(Box.createVerticalStrut(4));

		// Sort order button (toggles Ascending / Descending)
		sortOrderBtn.setAlignmentX(Component.LEFT_ALIGNMENT);
		sortOrderBtn.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		sortOrderBtn.addActionListener(e ->
		{
			sortAscending = !sortAscending;
			sortOrderBtn.setText(sortAscending ? "Ascending" : "Descending");
			refreshList();
		});
		header.add(sortOrderBtn);
		header.add(Box.createVerticalStrut(4));

		// Checkboxes in 2x2 grid
		JPanel checkGrid = new JPanel(new GridLayout(2, 2, 4, 2));
		checkGrid.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		checkGrid.setAlignmentX(Component.LEFT_ALIGNMENT);
		checkGrid.setMaximumSize(new Dimension(Integer.MAX_VALUE, 48));

		styleCheck(membersOnlyCheck);
		membersOnlyCheck.addActionListener(e -> refreshList());
		checkGrid.add(membersOnlyCheck);

		styleCheck(tradeableOnlyCheck);
		tradeableOnlyCheck.addActionListener(e -> refreshList());
		checkGrid.add(tradeableOnlyCheck);

		styleCheck(showHaCheck);
		showHaCheck.setSelected(config.showHaPrice());
		showHaCheck.addActionListener(e -> refreshList());
		checkGrid.add(showHaCheck);

		styleCheck(onlyUntradeableCheck);
		onlyUntradeableCheck.addActionListener(e -> refreshList());
		checkGrid.add(onlyUntradeableCheck);

		header.add(checkGrid);
		header.add(Box.createVerticalStrut(6));

		JButton refreshBtn = new JButton("Rescan Bank");
		refreshBtn.setAlignmentX(Component.LEFT_ALIGNMENT);
		refreshBtn.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		refreshBtn.addActionListener(e ->
		{
			if (onRescan != null)
			{
				onRescan.run();
			}
		});
		header.add(refreshBtn);

		// ===== Divider between settings and list =====
		JPanel northWrapper = new JPanel(new BorderLayout());
		northWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		northWrapper.add(header, BorderLayout.CENTER);

		JSeparator divider = new JSeparator(SwingConstants.HORIZONTAL);
		divider.setForeground(new Color(60, 60, 60));
		divider.setBackground(new Color(60, 60, 60));
		divider.setBorder(new EmptyBorder(4, 0, 4, 0));
		northWrapper.add(divider, BorderLayout.SOUTH);

		add(northWrapper, BorderLayout.NORTH);

		// ===== Item list =====
		itemListPanel.setLayout(new BoxLayout(itemListPanel, BoxLayout.Y_AXIS));
		itemListPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JScrollPane scroll = new JScrollPane(itemListPanel);
		scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		add(scroll, BorderLayout.CENTER);
	}

	private void styleCheck(JCheckBox box)
	{
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setForeground(Color.LIGHT_GRAY);
		box.setAlignmentX(Component.LEFT_ALIGNMENT);
	}

	public void setOnRescan(Runnable onRescan)
	{
		this.onRescan = onRescan;
	}

	public void updateItems(List<BankItem> items)
	{
		this.allItems = items != null ? new ArrayList<>(items) : new ArrayList<>();
		SwingUtilities.invokeLater(this::refreshList);
	}

	private void refreshList()
	{
		itemListPanel.removeAll();

		String search = searchField.getText().trim().toLowerCase();
		int minQty = parseIntSafe(minQtyField.getText(), 0);
		int minPrice = parseIntSafe(minPriceField.getText(), 0);
		boolean asc = sortAscending;
		SortMode mode = (SortMode) sortCombo.getSelectedItem();
		boolean membersOnly = membersOnlyCheck.isSelected();
		boolean tradeableOnly = tradeableOnlyCheck.isSelected();
		boolean showHa = showHaCheck.isSelected();
		boolean onlyUntradeable = onlyUntradeableCheck.isSelected();

		List<BankItem> filtered = allItems.stream()
			.filter(i -> !config.hidePlaceholders() || !i.isPlaceholder())
			.filter(i -> search.isEmpty() || i.getName().toLowerCase().contains(search))
			.filter(i -> i.getQuantity() >= minQty)
			.filter(i -> i.getGePrice() >= minPrice)
			.filter(i -> !membersOnly || i.isMembers())
			.filter(i -> !tradeableOnly || i.isTradeable())
			.filter(i -> !onlyUntradeable || !i.isTradeable())
			.collect(Collectors.toList());

		Comparator<BankItem> cmp;
		switch (mode)
		{
			case QUANTITY:
				cmp = Comparator.comparingInt(BankItem::getQuantity);
				break;
			case GE_PRICE:
				cmp = Comparator.comparingInt(BankItem::getGePrice);
				break;
			case TOTAL_VALUE:
				cmp = Comparator.comparingLong(BankItem::getTotalValue);
				break;
			case HA_PRICE:
				cmp = Comparator.comparingInt(BankItem::getHaPrice);
				break;
			case NAME:
			default:
				cmp = Comparator.comparing(BankItem::getName, String.CASE_INSENSITIVE_ORDER);
				break;
		}
		if (!asc)
		{
			cmp = cmp.reversed();
		}
		filtered.sort(cmp);

		long totalValue = 0;
		int totalStacks = filtered.size();
		long totalQty = 0;

		for (BankItem item : filtered)
		{
			totalValue += item.getTotalValue();
			totalQty += item.getQuantity();
			itemListPanel.add(createItemRow(item, showHa));
		}

		if (filtered.isEmpty())
		{
			JLabel empty = new JLabel(allItems.isEmpty()
				? "  No bank data yet — open your bank."
				: "  No items match the current filters.");
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			itemListPanel.add(empty);
		}

		statusLabel.setText(String.format("%d stacks  |  %,d total items", totalStacks, totalQty));
		totalLabel.setText("Bank GE value (filtered): " + QuantityFormatter.quantityToStackSize(totalValue) + " gp");

		itemListPanel.revalidate();
		itemListPanel.repaint();
	}

	private JPanel createItemRow(BankItem item, boolean showHa)
	{
		JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(4, 6, 4, 6));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));

		// Item icon on the left
		JLabel iconLabel = new JLabel();
		iconLabel.setPreferredSize(new Dimension(ICON_SIZE, ICON_SIZE));
		iconLabel.setMinimumSize(new Dimension(ICON_SIZE, ICON_SIZE));
		iconLabel.setHorizontalAlignment(SwingConstants.CENTER);
		try
		{
			AsyncBufferedImage img = itemManager.getImage(item.getId(), item.getQuantity(), false);
			if (img != null)
			{
				img.addTo(iconLabel);
			}
		}
		catch (Exception ignored)
		{
			// leave blank if image fails
		}
		row.add(iconLabel, BorderLayout.WEST);

		// Text details
		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setOpaque(false);

		JLabel nameLabel = new JLabel(item.getName());
		nameLabel.setForeground(Color.WHITE);
		text.add(nameLabel);

		StringBuilder detail = new StringBuilder();
		detail.append("x").append(QuantityFormatter.formatNumber(item.getQuantity()));

		// When High Alch is checked, show HA unit price instead of GE unit price
		if (showHa)
		{
			if (item.getHaPrice() > 0)
			{
				detail.append("  |  ").append(QuantityFormatter.quantityToStackSize(item.getHaPrice())).append(" ea");
			}
			if (config.showTotalValue() && item.getHaPrice() > 0)
			{
				long haTotal = (long) item.getQuantity() * item.getHaPrice();
				detail.append("  |  ").append(QuantityFormatter.quantityToStackSize(haTotal)).append(" total");
			}
		}
		else
		{
			if (config.showGePrice() && item.getGePrice() > 0)
			{
				detail.append("  |  ").append(QuantityFormatter.quantityToStackSize(item.getGePrice())).append(" ea");
			}
			if (config.showTotalValue() && item.getTotalValue() > 0)
			{
				detail.append("  |  ").append(QuantityFormatter.quantityToStackSize(item.getTotalValue())).append(" total");
			}
		}

		JLabel detailLabel = new JLabel(detail.toString());
		detailLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		text.add(detailLabel);

		row.add(text, BorderLayout.CENTER);

		// Right-click menu
		JPopupMenu popup = new JPopupMenu();
		JMenuItem wikiItem = new JMenuItem("Open Wiki");
		wikiItem.addActionListener(e -> openWiki(item));
		popup.add(wikiItem);

		JMenuItem copyName = new JMenuItem("Copy name");
		copyName.addActionListener(e -> {
			java.awt.Toolkit.getDefaultToolkit().getSystemClipboard()
				.setContents(new java.awt.datatransfer.StringSelection(item.getName()), null);
		});
		popup.add(copyName);

		JMenuItem copyId = new JMenuItem("Copy item ID");
		copyId.addActionListener(e -> {
			java.awt.Toolkit.getDefaultToolkit().getSystemClipboard()
				.setContents(new java.awt.datatransfer.StringSelection(String.valueOf(item.getId())), null);
		});
		popup.add(copyId);

		row.setComponentPopupMenu(popup);
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (SwingUtilities.isRightMouseButton(e))
				{
					popup.show(row, e.getX(), e.getY());
				}
			}
		});

		return row;
	}

	private void openWiki(BankItem item)
	{
		String url = WIKI_BASE + "Special:Lookup?type=item&id=" + item.getId();
		LinkBrowser.browse(url);
	}

	private static int parseIntSafe(String s, int def)
	{
		try
		{
			return Integer.parseInt(s.trim().replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return def;
		}
	}

	private static DocumentListener simpleListener(Runnable r)
	{
		return new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e) { r.run(); }
			@Override
			public void removeUpdate(DocumentEvent e) { r.run(); }
			@Override
			public void changedUpdate(DocumentEvent e) { r.run(); }
		};
	}
}

package com.bankscanner;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Bank Scanner",
	description = "Scans your bank when opened and lists items with quantities, prices, filtering and sorting. Right-click any item to open its OSRS Wiki page.",
	tags = {"bank", "items", "scanner", "filter", "sort", "wiki", "price", "quantity"}
)
public class BankScannerPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private BankScannerConfig config;

	@Inject
	private ClientToolbar clientToolbar;

	private BankScannerPanel panel;
	private NavigationButton navButton;

	@Override
	protected void startUp() throws Exception
	{
		panel = new BankScannerPanel(config, itemManager);
		panel.setOnRescan(this::scanBank);

		BufferedImage icon = loadIconSafely();

		navButton = NavigationButton.builder()
			.tooltip("Bank Scanner")
			.icon(icon)
			.priority(5)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		log.info("Bank Scanner started");
	}

	/**
	 * Never throws — returns a blank image if the resource is missing.
	 */
	private BufferedImage loadIconSafely()
	{
		// Paths relative to the class package and absolute classpath root
		String[] paths = {
			"icon.png",                 // com/bankscanner/icon.png
			"/icon.png",                // root of jar
			"/com/bankscanner/icon.png"
		};

		for (String path : paths)
		{
			try
			{
				BufferedImage img = ImageUtil.loadImageResource(BankScannerPlugin.class, path);
				if (img != null)
				{
					return img;
				}
			}
			catch (Throwable t)
			{
				// ImageUtil throws IllegalArgumentException when the resource is missing
			}
		}

		log.warn("Plugin icon not found — using blank icon");
		return new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
	}

	@Override
	protected void shutDown() throws Exception
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
		}
		if (panel != null)
		{
			panel.updateItems(null);
		}
		log.info("Bank Scanner stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN
			|| event.getGameState() == GameState.HOPPING)
		{
			if (panel != null)
			{
				panel.updateItems(null);
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.BANK.getId())
		{
			if (isBankOpen())
			{
				scanBank();
			}
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == 12)
		{
			clientThread.invokeLater(() ->
			{
				if (isBankOpen())
				{
					scanBank();
				}
			});
		}
	}

	public void scanBank()
	{
		clientThread.invoke(() ->
		{
			ItemContainer bank = client.getItemContainer(InventoryID.BANK);
			if (bank == null)
			{
				return;
			}

			List<BankItem> items = new ArrayList<>();
			Item[] containerItems = bank.getItems();
			if (containerItems == null)
			{
				return;
			}

			for (Item item : containerItems)
			{
				if (item == null)
				{
					continue;
				}
				int id = item.getId();
				int qty = item.getQuantity();
				if (id <= 0 || qty <= 0)
				{
					continue;
				}

				ItemComposition comp = itemManager.getItemComposition(id);
				if (comp == null)
				{
					continue;
				}

				int canonicalId = itemManager.canonicalize(id);
				int gePrice = itemManager.getItemPrice(canonicalId);
				int haPrice = comp.getHaPrice();

				boolean placeholder = comp.getPlaceholderTemplateId() == 14401 || qty == 0;

				String name = comp.getMembersName();
				if (name == null || name.isEmpty())
				{
					name = comp.getName();
				}

				items.add(new BankItem(
					id,
					name,
					qty,
					gePrice,
					haPrice,
					comp.isMembers(),
					comp.isTradeable(),
					placeholder
				));
			}

			if (panel != null)
			{
				panel.updateItems(items);
			}
			log.debug("Bank scanned: {} stacks", items.size());
		});
	}

	private boolean isBankOpen()
	{
		Widget bankContainer = client.getWidget(ComponentID.BANK_ITEM_CONTAINER);
		if (bankContainer == null)
		{
			bankContainer = client.getWidget(12, 12);
		}
		return bankContainer != null && !bankContainer.isHidden();
	}

	@Provides
	BankScannerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankScannerConfig.class);
	}
}

